            case CORRUPTED_GAUNTLET: return ItemID.CORRUPTED_YOUNGLLEF;
            case CHAMBERS_OF_XERIC:   return ItemID.OLMLET;
            //case THEATRE_OF_BLOOD:    return ItemID.LIL_ZIK;
